#include "stdafx.h"#include "HcdElementBase.h"struct SRTMR_P{#include "PrivateVars/RTMR.h"};class KRTMR : public KHcdElementBase  , protected SRTMR_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _RTMR("RTMR", KRTMR::Create);IHcdElement *KRTMR::Create(){  return new KRTMR;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KRTMR, 10 )void KRTMR::InitParm(){#include "PrivateVars/RTMR.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KRTMR::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KRTMR::StepCalc( SStepCalcParams &params ){  tAnalog32 time = Remote ? RPRES : LocalPreset;  if( RST )  {    if( TIM_DN )      TIME = time;    else      TIME = 0;    OUT = 0;    return;  }  if( !EN )    return;  if( TIM_DN )  {    TIME -= params.dtS;    if( TIME <=0 )    {      TIME = 0;      OUT = 1;    }  }  else  {    TIME += params.dtS;    if( TIME >= time )    {      TIME = time;      OUT = 1;    }  }}